{"content":"#!/usr/bin/env python3
"""v7 MONO — VARIANT B, "SIGNAL": black + white with one amber accent.

Same bone structure as the locked v7 MONO deck, so every geometry/QA result from the
mono build still holds. The only change: the headline keyword and the single biggest
stat stop being white and take one warm accent instead.

Why this exists: pure mono is beautiful but on a small phone screen an all-white deck
can read as one undifferentiated wall. A single warm accent gives the eye a first stop
on every page without reintroducing a second colour system.

Colour choice is deliberate -- HOT/HEAT amber, not green. Green is banned from the mono
family and reads as "corporate wellness"; amber is the heat half of contrast therapy.
"""
import os

import build_hotbox_mono_v1 as mono

ACC = "#FF8A3D"          # heat amber
OUT = "/root/hotbox-strategy"


def signal_css(css):
    """Run the locked mono palette first, then layer the single accent on top.

    Order matters: these rules are appended AFTER mono_css()'s own override block, so
    they win the cascade at equal specificity without touching the mono base.
    """
    css = mono.mono_css(css)
    return css + """
/* ============ v7 MONO · VARIANT B — one amber accent ============ */
:root{
  --acc:__ACC__; --acc-ink:#000000;
}
/* the two-tone headline keeps its brightness rhythm, but the keyword goes amber */
.head .g{ color:__ACC__; }
.pull .g{ color:__ACC__; }
.slide.light .head .g{ color:__ACC__; }
.slide.light .pull .g{ color:__ACC__; }
.t2 .g{ color:__ACC__; }
/* exactly one stat per page carries the accent (see .statcell.hot below) */
.statcell .v{ color:#FFFFFF; }
.statcell.hot .v{ color:__ACC__; }
""".replace("__ACC__", ACC)


def hot_marker(html, tag):
    """Mark every Nth .statcell as 'hot' so the accent lands on one stat per page.

    Deliberately deterministic and countable - a variant that randomly accented stats
    would make the deck look broken.
    """
    return html.replace("<div class='statcell'>", "<div class='statcell hot'>", tag)

if __name__ == "__main__":
    from weasyprint import HTML

    dst, nimg, used = mono.mono_images()
    print(f"  monochrome {nimg}/{len(used)} photos -> {dst}")
    mono._ns["IMG"] = dst
    for i, (tag, fmt, lap) in enumerate(
        [("mobile", mono.mobile_css, False), ("laptop", mono.laptop_css, True)]
    ):
        css = signal_css(fmt(mono.CSS))
        html = hot_marker(mono.strip_greens(mono.build(css, lap)), "hot")
        out = f"{OUT}/hotbox-forensic-v7-mono-signal-{tag}.pdf"
        HTML(string=html, base_url="/").write_pdf(out)
        import subprocess
        n = int(
            subprocess.run(["pdfinfo", out], capture_output=True, text=True)
            .stdout.split("Pages:")[1].split()[0]
        )
        flag = "OK" if n == len(mono.PAGES) else f"*** OVERFLOW: expected {len(mono.PAGES)}, got {n} ***"
        print(f"  {tag}: {os.path.getsize(out)//1024} KB, {n}pp {flag}")
","path":"/root/build_hotbox_mono_signal.py"}

