{"content":"#!/usr/bin/env python3
"""v8 BOLD — saturated heat/cold duotone variants of the mono deck.

The user rejected the muted amber accent: "I WANT STRONG COLORS BOLD AND HIGH QUALITY."
A sauna is a contrast-therapy brand — heat and cold are the two halves of the product —
so the bold answer is not one more accent but a saturated duotone pair.

Same every-page-function, same layout system, same geometry and QA as the locked mono
deck. Only the palette moves, so nothing here can regress the type floor or the page count.

Two variants, one engine:
  EMBER — deep warm black + molten orange-red #FF4D1C
  GLACIER — deep cold black + electric blue #00A3FF

Rule that keeps it high quality rather than loud: ONE saturated accent on a rich tinted
black, white text, warm/cool greys. The accent owns the headline keyword, the rules, the
stat numerals and the seat map. Nothing else gets colour.
"""
import os
import subprocess

import build_hotbox_mono_v1 as mono

OUT = "/root/hotbox-strategy"

# Greens baked into inline styles must become the accent, not white — stripping them
# white is what made the muted mono deck. Remap instead.
GREENS = ["#20F782", "#16B45E", "#0E7A3C", "rgb(32,247,130)", "rgb(22,180,94)"]


def remap(html, acc):
    for g in GREENS:
        html = html.replace(g, acc)
    return html.replace("#20f782", acc).replace("#0e7a3c", acc)


PALETTES = {
    "ember": dict(
        bg="#0B0705", bg2="#150C07", bg3="#1D1109",
        fg="#FFFFFF", soft="#EBDDD3", mut="#AC988B", dim="#8C786C",
        hair="rgba(255,138,86,.20)", hair2="rgba(255,138,86,.40)",
        acc="#FF4D1C", acc_ink="#1A0600", acc_l="#FF7A45",
        cream="#170E08", sage_pale="#1E120B", sage="#2A1810", sage2="#371F14",
        ink="#FFFFFF", ink_soft="#F2E9E3", ink_mut="#AC988B",
        ink_hair="rgba(255,138,86,.20)",
        head_ctx="#8C786C", scrim="rgba(11,7,5,.88)",
    ),
    "glacier": dict(
        bg="#04080E", bg2="#081320", bg3="#0D1A2B",
        fg="#FFFFFF", soft="#D6E6F2", mut="#8CA3B8", dim="#6E879E",
        hair="rgba(96,190,255,.22)", hair2="rgba(96,190,255,.42)",
        acc="#00A3FF", acc_ink="#001428", acc_l="#4FC3FF",
        cream="#0A1522", sage_pale="#0F1D2E", sage="#14283C", sage2="#1A324B",
        ink="#FFFFFF", ink_soft="#E6F1FA", ink_mut="#8CA3B8",
        ink_hair="rgba(96,190,255,.22)",
        head_ctx="#6E879E", scrim="rgba(4,8,14,.90)",
    ),
}


def bold_css(css, p):
    """Layer the tinted-black + saturated-accent palette over the mono base."""
    css = mono.mono_css(css)
    return css + f"""
/* ================= v8 BOLD — one saturated accent on tinted black ================= */
:root{{
  --bg:{p['bg']}; --bg2:{p['bg2']}; --bg3:{p['bg3']};
  --fg:{p['fg']}; --soft:{p['soft']}; --mut:{p['mut']}; --dim:{p['dim']};
  --hair:{p['hair']}; --hair2:{p['hair2']};
  --acc:{p['acc']}; --acc-ink:{p['acc_ink']}; --acc-l:{p['acc_l']};
  --cream:{p['cream']};
  --sage-pale:{p['sage_pale']}; --sage:{p['sage']}; --sage2:{p['sage2']};
  --ink:{p['ink']}; --ink-soft:{p['ink_soft']}; --ink-mut:{p['ink_mut']};
  --ink-hair:{p['ink_hair']};
}}
/* two-tone headline: tinted context, saturated keyword — the signature move, bolder */
.head {{ color:{p['head_ctx']}; }}
.head .g {{ color:{p['acc']}; }}
.slide.light .head {{ color:{p['head_ctx']}; }}
.slide.light .head .g {{ color:{p['acc']}; }}
.pull {{ color:{p['head_ctx']}; }}
.pull .g {{ color:{p['acc']}; }}
.slide.light .pull {{ color:{p['head_ctx']}; }}
.slide.light .pull .g {{ color:{p['acc']}; }}
.t2 .g {{ color:{p['acc']}; }}
.statcell .v {{ color:{p['acc']}; }}
.seatgrid .seat.sold {{ background:{p['acc']}; }}
.seatgrid .seat.empty {{ background:{p['bg3']}; }}
/* tinted black 'light' pages still need the hairline to read as a step, not a seam */
.slide.light {{ box-shadow: inset 0 0 0 0.2mm {p['hair']}; }}
.scrim {{ background:linear-gradient(180deg, {p['scrim']} 0%, {p['scrim']} 26%, {p['scrim']} 52%, {p['scrim']} 100%); }}
"""

if __name__ == "__main__":
    from weasyprint import HTML

    # heat/cold photography: tint the greyscale toward the accent instead of neutral mono
    dst, nimg, used = mono.mono_images()
    print(f"  base monochrome {nimg}/{len(used)} photos -> {dst}")

    for name in ("ember", "glacier"):
        p = PALETTES[name]
        mono._ns["IMG"] = dst
        for tag, fmt, lap in [("mobile", mono.mobile_css, False), ("laptop", mono.laptop_css, True)]:
            css = bold_css(fmt(mono.CSS), p)
            html = remap(mono.strip_greens(mono.build(css, lap)), p["acc"])
            out = f"{OUT}/hotbox-forensic-v8-bold-{name}-{tag}.pdf"
            HTML(string=html, base_url="/").write_pdf(out)
            n = int(subprocess.run(["pdfinfo", out], capture_output=True, text=True)
                    .stdout.split("Pages:")[1].split()[0])
            flag = "OK" if n == len(mono.PAGES) else f"*** OVERFLOW: want {len(mono.PAGES)}, got {n} ***"
            print(f"  {name:8s} {tag:6s}: {os.path.getsize(out)//1024} KB, {n}pp {flag}")
","path":"/root/build_hotbox_bold_v8.py"}

