import zlib, re, subprocess, xml.etree.ElementTree as ET, collections

TARGETS = {
 "hotbox-forensic-v8-bold-ember-laptop.pdf":  (1.0, 0.302, 0.110),  # FF4D1C
 "hotbox-forensic-v8-bold-glacier-laptop.pdf": (0.0, 0.639, 1.0),   # 00A3FF
 "hotbox-forensic-v7-mono-laptop.pdf":         None,                # control: no green
}
GREEN = (0.125, 0.969, 0.510)  # 20F782

def colours(pdf):
    raw = open(pdf,'rb').read()
    counts = collections.Counter()
    for m in re.finditer(rb'stream\r?\n', raw):
        s = m.end(); e = raw.find(b'endstream', s)
        if e < 0: continue
        try: data = zlib.decompress(raw[s:e])
        except Exception: continue
        for cm in re.finditer(rb'([\d.]+) ([\d.]+) ([\d.]+) (rg|RG)', data):
            counts[(round(float(cm.group(1)),3), round(float(cm.group(2)),3), round(float(cm.group(3)),3))] += 1
    return counts

def floor(pdf):
    xml = subprocess.run(["pdftotext","-bbox-layout",pdf,"-"],capture_output=True,text=True).stdout
    root = ET.fromstring(xml)
    loc = lambda t: t.split('}')[-1]
    hs=[round(float(w.attrib['yMax'])-float(w.attrib['yMin']),1) for w in root.iter() if loc(w.tag)=='word' and 'yMax' in w.attrib]
    return len(hs), min(hs), sum(1 for h in hs if h<8)

for pdf, want in TARGETS.items():
    c = colours(pdf); n,f,u = floor(pdf)
    if want:
        hits = sum(v for k,v in c.items() if all(abs(k[i]-want[i])<0.02 for i in range(3)))
        green = sum(v for k,v in c.items() if all(abs(k[i]-GREEN[i])<0.02 for i in range(3)))
        print(f"  {pdf.split('v8-bold-')[-1] if 'v8' in pdf else pdf}")
        print(f"    accent ops: {hits}   |   leftover GREEN ops: {green}   |   words {n}, floor {f}pt, under-8 {u}")
    else:
        green = sum(v for k,v in c.items() if all(abs(k[i]-GREEN[i])<0.02 for i in range(3)))
        white = sum(v for k,v in c.items() if all(abs(k[i]-1.0)<0.02 for i in range(3)))
        print(f"  v7-mono (control): green ops {green} | white ops {white} | words {n}, floor {f}pt, under-8 {u}")
PY","timeout":300}
